import{_ as d,a0 as p,w as e,s as l,I as i,x as o,a1 as r,A as s,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 图形栈上运行 Android | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 图形栈上运行 Android | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 图形栈上运行 Android | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 图形栈上运行 Android | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171020 Running Android on Top of a Linux Graphics Stack","title":"在 Linux 图形栈上运行 Android","tag":"201711","desc":""},"relativePath":"201711/20171020 Running Android on Top of a Linux Graphics Stack.md","filePath":"[post].md"}'),a={name:"201711/20171020 Running Android on Top of a Linux Graphics Stack.md"};function x(A,n,L,g,m,f){const t=p("Link");return e(),l("div",null,[n[18]||(n[18]=i("h1",{id:"在-linux-图形栈上运行-android",tabindex:"-1"},[o("在 Linux 图形栈上运行 Android "),i("a",{class:"header-anchor",href:"#在-linux-图形栈上运行-android","aria-label":"Permalink to “在 Linux 图形栈上运行 Android”"},"​")],-1)),n[19]||(n[19]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/linux-graphics-stack.jpg?itok=qGxdvJA7",alt:"Linux graphics",title:"Linux graphics"})],-1)),i("blockquote",null,[i("p",null,[n[1]||(n[1]=o("根据 Collabora 的 Linux 图形栈贡献者和软件工程师 Robert Foss 的说法，你现在可以在常规的 Linux 图形处理平台上运行 Android，这是非常强大的功能。了解更多关于他在欧洲嵌入式 Linux 会议上的演讲。",-1)),r(t,{href:"https://www.linux.com/licenses/category/creative-commons-zero"},{default:s(()=>[...n[0]||(n[0]=[o("Creative Commons Zero",-1)])]),_:1}),n[2]||(n[2]=o(" Pixabay",-1))])]),i("p",null,[n[4]||(n[4]=o("你现在可以在常规的 Linux 图形栈之上运行 Android。以前并不能这样，根据 Collabora 的 Linux 图形栈贡献者和软件工程师 Robert Foss 的说法，这是非常强大的功能。在即将举行的",-1)),r(t,{href:"http://events.linuxfoundation.org/events/embedded-linux-conference-europe"},{default:s(()=>[...n[3]||(n[3]=[o("欧洲 Linux 嵌入式会议",-1)])]),_:1}),n[5]||(n[5]=o("的讲话中，Foss 将会介绍这一领域的最新进展，并讨论这些变化如何让你可以利用内核中的新功能和改进。",-1))]),n[20]||(n[20]=u("<p>在本文中，Foss 解释了更多内容，并提供了他的演讲的预览。</p><p><strong>Linux.com：你能告诉我们一些你谈论的图形栈吗？</strong></p><p><strong>Foss：</strong> 传统的 Linux 图形系统（如 X11）大都没有使用<ruby>平面图形<rt>plane</rt></ruby>。但像 Android 和 Wayland 这样的现代图形系统可以充分利用它。</p><p>Android 在 HWComposer 中最成功实现了平面支持，其图形栈与通常的 Linux 桌面图形栈有所不同。在桌面上，典型的合成器只是使用 GPU 进行所有的合成，因为这是桌面上唯一有的东西。</p><p>大多数嵌入式和移动芯片都有为 Android 设计的专门的 2D 合成硬件。这是通过将显示的内容分成不同的图层，然后智能地将图层送到经过优化处理图层的硬件。这就可以释放 GPU 来处理你真正关心的事情，同时它让硬件更有效率地做最好一件事。</p><p><strong>Linux.com：当你说到 Android 时，你的意思是 Android 开源项目 （AOSP） 么？</strong></p><p><strong>Foss：</strong> Android 开源项目（AOSP）是许多 Android 产品建立的基础，AOSP 和 Android 之间没有什么区别。</p><p>具体来说，我的工作已经在 AOSP 上完成，但没有什么可以阻止将此项工作加入到已经发货的 Android 产品中。</p><p>区别更多在于授权和满足 Google 对 Android 产品的要求，而不是代码。</p><p><strong>Linux.com： 谁想要运行它，为什么？有什么好处？</strong></p><p><strong>Foss：</strong> AOSP 为你提供了大量免费的东西，例如针对可用性、低功耗和多样化硬件进行优化的软件栈。它比任何一家公司自行开发的更精致、更灵活, 而不需要投入大量资源。</p><p>作为制造商，它还为你提供了一个能够立即为你的平台开发的大量开发人员。</p><p><strong>Linux.com：有什么实际使用情况？</strong></p><p>** Foss：** 新的部分是在常规 Linux 图形栈上运行 Android 的能力。可以在主线/上游内核和驱动来做到这一点，让你可以利用内核中的新功能和改进，而不仅仅依赖于来自于你的供应商的大量分支的 BSP。</p><p>对于任何有合理标准的 Linux 支持的 GPU，你现在可以在上面运行 Android。以前并不能这样。而且这样做是非常强大的。</p><p>同样重要的是，它鼓励 GPU 设计者与上游的驱动一起工作。现在他们有一个简单的方法来提供适用于 Android 和 Linux 的驱动程序，而无需额外的努力。他们的成本将会降低，维护上游 GPU 驱动变得更有吸引力。</p><p>例如，我们希望看到主线内核支持高通 SOC，我们希望成为实现这一目标的一部分。</p><p>总而言之，这将有助于硬件生态系统获得更好的软件支持，软件生态系统有更多的硬件配合。</p><ul><li>它改善了 SBC/开发板制造商的经济性：它们可以提供一个经过良好测试的栈，既可以在两者之间工作，而不必提供 “Linux 栈” 和 Android 栈。</li><li>它简化了驱动程序开发人员的工作，因为只有一个优化和支持目标。</li><li>它支持 Android 社区，因为在主线内核上运行的 Android 可以让他们分享上游的改进。</li><li>这有助于上游，因为我们获得了一个产品级质量的栈，这些栈已经在硬件设计师的帮助下进行了测试和开发。</li></ul><p>以前，Mesa 被视为二等栈，但现在它是最新的（完全符合 Vulkan 1.0、OpenGL 4.6、OpenGL ES 3.2）另外还有性能和产品质量。</p><p>这意味着驱动开发人员可以参与 Mesa，相信他们正在分享他人的辛勤工作，并且还有一个很好的基础。</p><hr>",22)),i("p",null,[n[7]||(n[7]=o("via: ",-1)),r(t,{href:"https://www.linux.com/blog/event/elce/2017/10/running-android-top-linux-graphics-stack"},{default:s(()=>[...n[6]||(n[6]=[o("https://www.linux.com/blog/event/elce/2017/10/running-android-top-linux-graphics-stack",-1)])]),_:1})]),i("p",null,[n[10]||(n[10]=o("作者：",-1)),r(t,{href:"https://www.linux.com/users/arnieswap"},{default:s(()=>[...n[8]||(n[8]=[o("SWAPNIL BHARTIYA",-1)])]),_:1}),n[11]||(n[11]=o(" 译者：",-1)),r(t,{href:"https://github.com/geekpi"}),n[12]||(n[12]=o(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:s(()=>[...n[9]||(n[9]=[o("wxy",-1)])]),_:1})]),i("p",null,[n[15]||(n[15]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[13]||(n[13]=[o("LCTT",-1)])]),_:1}),n[16]||(n[16]=o(" 原创编译，",-1)),r(t,{href:"https://linux.cn/"},{default:s(()=>[...n[14]||(n[14]=[o("Linux中国",-1)])]),_:1}),n[17]||(n[17]=o(" 荣誉推出",-1))])])}const P=d(a,[["render",x]]);export{w as __pageData,P as default};
